insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 1, 'The 2030 row of the hand-derived joint venture case reads revenue 100000000.00, royalty 20000000.00, opex 10000000.00, capex 50000000.00, depreciation 5000000.00 and tax 32500000.00. What is the row''s net cash flow?', '["-17500000.00, because depreciation is a cost like opex and comes off the cash view as well as the tax view.", "37500000.00, because capex is recovered through depreciation and so does not belong in the cash view of the row.", "-12500000.00, because depreciation only reduces taxable income and is not cash leaving the account in that year.", "-7500000.00, because the royalty is the government''s share and is not an outflow from the operator''s account."]'::jsonb, 2, 'Revenue less royalty, opex, capex 50000000.00 and tax is -12500000.00; the 5000000.00 of depreciation appears nowhere in the net cash flow column.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 2, 'The hand-derived case reports take 80.7692 percent and payback 1.33 years. What kind of numbers are these?', '["Readings of the ledger under a convention: take is a ratio of columns and payback is where the cumulative column crosses zero.", "Inputs the engine was configured with, alongside the royalty of 20 percent and the tax rate of 50 percent.", "Properties of the field that would survive a change of price or escalator.", "Outputs of a separate reservoir model that the ledger is built on."]'::jsonb, 0, 'Neither is a new fact; each is the two-row ledger read a particular way, and the convention it was read under travels with it or it means nothing.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 3, 'What does a row of the ledger refuse to carry?', '["A negative net cash flow, which is moved into the loss carryforward column so that the row itself never reads below 0.00.", "More than one well, since the ledger keeps one row per well per year and a field with two wells has twice the rows.", "Depreciation, which belongs to the tax computation and is kept off the ledger entirely.", "Months and an order of events: January capex and December revenue sit together as if they happened at once."]'::jsonb, 3, 'The engine reads dates and month indexes on upload, but the ledger it returns has one row per year and there is no cash flow of March, which is what an end-year convention assumes.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 4, 'The 2031 row of the hand-derived case is net cash flow 37500000.00 against -12500000.00 in 2030. Why do they differ by exactly the capex, 50000000.00?', '["Depreciation finished in 2030, so the 2031 row carries no deduction and the whole capex comes back as cash.", "Capex is 0.00 in 2031 and everything else is identical, including depreciation 5000000.00, so tax is unchanged at 32500000.00.", "The 2031 revenue was escalated over 2030 by exactly enough to cover the capex, so the two rows balance to it.", "The 2030 loss of 12500000.00 was carried forward and relieved in 2031, which is what lifts the second row."]'::jsonb, 1, 'Depreciation is 5000000.00 in both rows and taxable income is 65000000.00 in both, so the cash difference is the one column that changed.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 5, 'What does the Petroleum Economics Studio engine, version 3.9.0, read before it builds a ledger?', '["Three uploaded files, production, capex and opex, and a configuration carrying prices, escalators, inflation and fiscal terms; nothing else.", "A production file, a reservoir decline model and a facilities capacity file, from which it checks the volumes before believing them.", "A single combined spreadsheet of volumes and costs, with the price taken from the deck by default when the configuration is blank.", "The three files and a well log, which fixes the boe conversion for the field."]'::jsonb, 0, 'If the volumes are wrong the ledger is wrong, and the engine has no way to know: no reservoir, no facilities capacity, no decline.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 6, 'Which published case reports take as null, and what was zero in it?', '["single_year_positive, where capex is 0.00, so there is no investment base for the ratio to divide by.", "psc_carryforward, where total tax 27000000.00 exceeds the total net cash flow of -1000000.00, so take is above 100 percent and reported null.", "zero_rates_capex_only, where total revenue is 0.00, so take and unit technical cost come back null rather than as a ratio with nothing on top.", "per_well_beats_total_rollup, where opex is 0.00, so no unit cost can be formed."]'::jsonb, 2, 'psc_carryforward reports take 101.0000 percent and single_year_positive 61.1111 percent; null is the engine declining to invent a ratio when revenue is 0.00.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 7, 'multiyear_pia_nominal and multiyear_pia_real are one field with one set of rows, and they report total net cash flow 329879515.51 and 286158487.25. Which is wrong?', '["The nominal one, because inflation has been added to flows that were already escalated, which counts it twice.", "Neither: one is money of the day and the other money of the base year, and a total without its basis is not a number.", "The real one, because it has been discounted at the applied real rate of 6.796117 percent and is the NPV of 203250580.21 under another name.", "The nominal one, since only the real basis is a valid reading of a PIA ledger."]'::jsonb, 1, 'The ledger carries a net_cash_flow and a real_net_cash_flow column, and their totals part once inflation is set.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 8, 'AKATA reports total revenue 857602518.80. What is that number a property of?', '["The field, since the volumes of 9680000.00 bbl and 7744000.00 Mscf are fixed by the upload and the total revenue follows them whatever the configuration says about price.", "The price alone, because volumes do not enter a revenue total until the boe conversion at 6 Mscf per barrel has been applied to fold the gas into the oil.", "The base year, because every total is restated in money of the base year 2029 through the inflation rate, so a total is a property of the year it is quoted in.", "The run: a price of 82 escalating at 2 percent on those volumes, so changing the escalator moves the total while the field does not."]'::jsonb, 3, 'Learn the settings that produced a number before you learn the number.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 9, 'A capex row carries amount_usd=30000000 and cost_usd=30000000. What does the engine do with it?', '["It accepts the row once and the year''s capex is 30000000.00; only different values in two cost columns are refused.", "It refuses the run as ambiguous_cost_aliases, since two populated cost columns in one row is exactly the ambiguity the message names.", "It sums both through the *_usd fallback, because two preferred aliases cancel each other and the parts rule takes over.", "It takes the first alias on its list, amount_usd, and warns that cost_usd was dropped."]'::jsonb, 0, 'The refusal message says which: different values, refused; the same value, taken once, which is the duplicate_identical_aliases case at capex 30000000.00.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 10, 'The case_insensitive_headers upload carries Water_BBL=20000 beside Oil_BBL=100000 for 2027. What happens?', '["The run is refused as no_volume_columns, because water is not one of the oil, gas or condensate volumes the message lists.", "The water is priced at the oil price of 75, since any column ending in _bbl is a barrel of liquid to the engine, and revenue rises above 7500000.00.", "The water is netted off the oil to give the sales volume, since the engine reads water as a cut of the liquid.", "The run proceeds, 20000.00 bbl of water is read into the annual volumes, and revenue is 7500000.00 from the 100000.00 bbl of oil alone."]'::jsonb, 3, 'Unrecognised against unpriced: oil_production stops the run, but water_bbl is a volume column that earns nothing, silently.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 11, 'The hand-derived case sets gas_price_usd_mscf=0 and every row has gas_mscf 0.00. Does gas_price_unset fire?', '["Yes, because a gas price of 0 is the same as an unset price and the check reads the configuration, not the volumes.", "No, because the engine prices the gas at one sixth of the oil price of 100.000000 through the boe conversion.", "No, because gas_price_unset fires only when the production data has gas volumes, and there are none.", "Yes, and the run continues with a warning while gas revenue is booked at 0.00."]'::jsonb, 2, 'The refusal is about the pair: an unset gas_price_usd_mscf with gas volumes in the file, and the hand-derived case has neither.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 12, 'A capex row reads drilling_usd=20000000, facilities_usd=5000000 and total_usd=99. What does the refusal machinery do with the 99?', '["It refuses the row as ambiguous_cost_aliases, because three cost columns in one row hold three different values, which is the ambiguity the message says it will not resolve by picking one.", "Nothing: the 99 is ignored because of its total_ prefix, capex is 25000000.00, and the only trace is in the annual capex the engine reports back.", "It prefers the total, since a column named total is the rollup the spreadsheet author checked, and the year''s capex reads 99 while drilling_usd and facilities_usd are carried past as parts.", "It sums all three columns, the total included, since every column ending in _usd is a cost to the fallback and nothing preferred was present to stop the sum from running."]'::jsonb, 1, 'The engine refuses what it cannot read; it does not refuse what it can read and should not believe.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 13, 'AKATA''s totals are oil 9680000.00 bbl and gas 7744000.00 Mscf, and the reported boe is 10970666.67. What converts between the two volumes?', '["The field''s own gas to oil ratio of 800 scf per barrel, read from the upload, so a richer field converts at a richer ratio.", "6 Mscf per barrel, fixed: gas counts at one sixth of a barrel per Mscf and condensate counts as a barrel.", "The ratio of the two prices, 3.200000 against 82.000000, so that a barrel of oil equivalent is a barrel of equal value.", "A conversion set in the configuration, with 6 as the default."]'::jsonb, 1, 'The convention is fixed, which is why the three-stream case reports boe 10300000.00 from oil 5000000.00, condensate 300000.00 and gas 30000000.00 Mscf.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 14, 'jv_royalty_pct=15 means 15 percent. What does the engine do if a reader enters the fraction instead?', '["It refuses the run, since a rate below 1 falls outside the range a percent field accepts.", "It recognises a value below 1 as a fraction and converts it, so the ledger reads the same 15 percent either way.", "It runs, but reports the royalty column at 0.00 because the fraction rounds away at two decimals.", "It runs a royalty a hundred times smaller than intended, without objection."]'::jsonb, 3, 'Percent is a unit that travels with every rate column, and the units refuse to convert: a file in the wrong unit is believed at full precision.'),
  ('cashflow', 'beginner', 'module', 'm01-what-a-cash-flow-is', 15, 'A file lists gas in scf under an _mscf header. What does the engine do?', '["It believes the file: the gas is read a thousand times too large and every number downstream carries the error at full precision.", "It refuses the file, because the gas volumes are inconsistent with the 800 scf per barrel that AKATA''s oil and gas columns imply, and the check is made at the door.", "It converts the column, since the header names the unit and the engine reads the thousand out of _mscf on the way in.", "It flags the row with a warning and prices the gas at 0.00 until the header is corrected."]'::jsonb, 0, 'AKATA''s upload column is akata_gas_mscf with 1760000 against 2200000 bbl: the thousand is in the header, and nothing objects to a mismatch.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 1, 'Which of these headers does the engine read as a volume column, and why?', '["w1_oil_bbl_forecast, because the well prefix and the oil suffix are both present and the trailing word is a label the engine carries past.", "total_oil_bbl, because the suffix _oil_bbl closes the header; w1_oil_bbl_forecast fails because forecast follows the suffix.", "oil, because the engine matches on the stream name and treats the unit suffix as optional.", "oil_price_usd_bbl, because it ends in _bbl and every _bbl column is a barrel."]'::jsonb, 1, 'The suffix must be last and case does not matter, so OIL_BBL is the same column as oil_bbl while oil_price_usd_bbl, which ends in _bbl but not in _oil_bbl, is not a volume.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 2, 'The alaoma_csv_ingestion upload has date=2027-01 with oil_bbl=100000 and date=2027-02 with oil_bbl=90000. What does the ledger read for 2027?', '["Two rows, 100000.00 bbl and 90000.00 bbl, because each dated row becomes a row of the ledger and the year is a label on it.", "Oil 120000.00 bbl, because liquid_bbl is the larger volume column in the first row and the engine takes the total liquid.", "Oil 100000.00 bbl, because a second row in the same year needs a month_index before it can be added.", "Oil 190000.00 bbl in one row, because every volume in every row with the same year is added into that year."]'::jsonb, 3, 'The engine reads 2027 as oil 190000.00 bbl, gas 0.00 Mscf, condensate 0.00 bbl and water 45000.00 bbl, and nothing in that ledger knows it was uploaded monthly.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 3, 'The same upload carries days_in_month, liquid_bbl, oil_rate_bopd and watercut_pct beside oil_bbl. What does the engine do with them?', '["It carries them past unread, because none ends in a volume suffix.", "It uses oil_rate_bopd and days_in_month to check oil_bbl and refuses the file if the product disagrees with the volume.", "It reads liquid_bbl as the sales volume and derives oil from it using watercut_pct.", "It refuses the file, since unrecognised columns beside a volume column are the ambiguity the ambiguous_cost_aliases message describes."]'::jsonb, 0, 'Every silent drop is a check the reader makes on the annual volumes the engine reports back: 190000.00 bbl of oil against the spreadsheet''s own sum.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 4, 'The month_index_rows case uploads an opex row of total_opex_usd=1000000 at month_index=13 with base_year 2027. Which ledger year does it join?', '["2027, because 13 is within the 24 months of the upload and the engine files all of them in base_year.", "2029, because month 1 is the year after base_year and month 13 the year after that.", "2028, because month_index 13 is the first month of the year after base_year.", "2027, because opex rows are matched to the production year they support, and production began in 2027."]'::jsonb, 2, 'month_index counts months from the base year: 1 to 12 land in base_year and 13 to 24 in the next, so the ledger reads 2027 opex none and 2028 opex 1000000.00.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 5, 'alaoma_csv_ingestion has capex rows dated 2027-01 for 30000000 and 2027-06 for 10000000. What does the ledger show?', '["One 2027 capex of 40000000.00; the month locates the year and is then forgotten.", "30000000.00 in 2027 and 10000000.00 in 2028, because a June date is past the middle of the year and rolls forward.", "Two capex entries in 2027, January and June, so that the mid-year convention can weight them by month.", "40000000.00 in 2027 with the June spend escalated by five months of the capex escalator."]'::jsonb, 0, 'Dating happens before any price or escalator is applied, and rows in the same year add: the ledger has no months.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 6, 'A production file has volumes but no year, date or month_index column. What does the engine do?', '["It numbers the rows 1, 2, 3 as month indexes from base_year, since a row order is a date in all but name.", "It puts every row into base_year and proceeds, since base_year is the one year it is sure of.", "It refuses with no_usable_date; it does not read a year from a filename, from row order or from a column called period.", "It refuses with no_production_rows, because rows without a date are not production rows."]'::jsonb, 2, 'The engine does not infer a date, and the same refusal fires when the column exists but no row holds a usable value.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 7, 'A reader numbers month indexes from the first production month, but production starts in the second year of the model. What happens to the ledger?', '["The engine refuses with no_usable_date, because a month index that does not start at base_year is unusable.", "Every volume, every escalated price and every cumulative figure shifts a year early, and the ledger looks complete.", "Nothing changes, because month indexes are relative to the first row of the file and the engine anchors them there rather than at base_year.", "The volumes shift a year early but the prices do not, since prices are applied by calendar year."]'::jsonb, 1, 'The check is the plainest reading: month_index=13 is the first month of the year after base_year, so month_index=13 opex must show up in the second row, as the 1000000.00 does.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 8, 'per_well_beats_total_rollup uploads total_oil_bbl=100000, well1_oil_bbl=60000 and well2_oil_bbl=40000 for 2027. What does the engine read, and by which rule?', '["200000 bbl, since all three headers pass the volume test and every volume column in a year is added into that year.", "100000.00 bbl, read from total_oil_bbl, because a total column is preferred over the parts in the same way total_opex_usd is preferred among cost aliases.", "60000.00 bbl, the well nearest the dropped total.", "100000.00 bbl: the wells are summed and the total is dropped."]'::jsonb, 3, 'Had the total been added to the wells, revenue would have been double 7500000.00 and every reading built on it wrong by the same factor, and nothing in the KPI panel would have looked odd.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 9, 'How does the cost side''s rule for a total column compare with the volume side''s?', '["For volumes the total is ignored when wells exist; for costs a total_ prefixed column is excluded from the parts sum. In both, the pieces beat the rollup.", "They are opposite: volumes take the total and drop the wells, while costs drop the total and sum the parts.", "They are the same: the total is added to the parts in both lanes, which is why usd_fallback_parts reports 25000000.00.", "Costs have no rule for totals, since a cost file carries one amount per row."]'::jsonb, 0, 'drilling_usd=20000000 and facilities_usd=5000000 with total_usd=99 give capex 25000000.00, and the 99 never enters.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 10, 'well1 and well2 sum to something other than total_oil_bbl. What does the engine report?', '["A warning naming the total it dropped, so that the reader can decide which number the field actually sold.", "The wells'' sum, and nothing about the total it dropped: it does not warn, does not reconcile and does not use the total to check the wells.", "The total, since a disagreement means the wells are incomplete and the total is the safer figure.", "A refusal, because a total that disagrees with its parts is the ambiguity the engine will not resolve."]'::jsonb, 1, 'Every one of those checks is one the reader does, by comparing the annual volume the engine reports against the file.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 11, 'alaoma_csv_ingestion''s opex rows carry fixed_opex_usd, variable_oil_usd, variable_water_usd, unit_opex_usd_per_bbl and total_opex_usd of 750000 then 740000. What is the 2027 opex?', '["1000000.00, from fixed_opex_usd of 500000 in each month, because the preferred alias list begins with the fixed component.", "The total plus the parts, because a preferred alias takes the total and the *_usd fallback then adds every other cost column to it.", "The unit rate of 7.5 times the oil, because a per barrel column is the one tied to the volumes.", "1490000.00, from total_opex_usd both times; the parts are not added and the unit rate is not multiplied by anything."]'::jsonb, 3, 'A preferred alias, when present, is the amount; the rest of the row is carried past.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 12, 'In usd_fallback_parts the capex row is drilling_usd=20000000, facilities_usd=5000000 and total_usd=99. If total_usd is renamed total_capex_usd, what does capex read?', '["25000000.00 still, because a total_ prefixed column is excluded from every sum whatever its full name.", "The row is refused as ambiguous_cost_aliases, because a preferred alias and two *_usd parts now hold different values.", "99, because total_capex_usd is a preferred alias, and a preferred alias when present is the amount while the parts are carried past.", "25000000.00, because the engine compares the alias against the parts and keeps the parts when they disagree."]'::jsonb, 2, 'The fallback only runs when nothing preferred is there to stop it, so the same amounts under a different header give a different ledger.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 13, 'A capex file headed category, date, spend is refused. What single change lets it through?', '["Give the cost column a name ending in _usd, since the fallback sums *_usd columns and spend has no unit in its name.", "Rename spend to cost, because the word cost is on the preferred alias list as cost_usd and the engine matches on the word, not the suffix.", "Add a total_usd column holding the sum, which the fallback prefers as the rollup.", "Nothing short of the exact header amount_usd, which is the one name a capex file must carry."]'::jsonb, 0, 'The unit is in the header or the column is not a cost; Cost_USD in case_insensitive_headers was read as 30000000.00 because case is ignored but the suffix is not.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 14, 'usd_fallback_parts, alaoma_csv_ingestion in both its production and its opex file, per_well_beats_total_rollup and case_insensitive_headers each dropped a column silently. What did a reader watching only for refusals see?', '["Four warnings, one per case, since a dropped column is logged against the row it came from even when the run proceeds, and the KPI panel carries a count of the columns it did not read.", "Five successes: nothing was refused, every run produced a clean ledger, and the drops show only in the annual volumes, capex and opex read back against the file.", "One refusal, the ambiguous_cost_aliases case, since two of the dropped columns were cost aliases holding values different from the one the engine read, and that is the ambiguity the message names.", "Nothing at all, because the KPI panel goes blank when a column is dropped."]'::jsonb, 1, 'The refusals guard the door; once inside, the engine drops what it does not recognise without a word, and those drops are the failures to worry about.'),
  ('cashflow', 'beginner', 'module', 'm02-from-rows-to-years', 15, 'per_well_beats_total_rollup was run with no opex file at all. What does the refusal machinery do?', '["It refuses with opex_no_cost_column, because a missing opex file has no cost column to recognise.", "It refuses with no_production_rows, since a run needs all three files before it can build a ledger.", "Nothing: the run proceeds with total opex 0.00, because the refusals check that a recognised header exists, not that opex is present or that the number under it is right.", "It runs, but fills opex from unit_opex_usd_per_bbl times the annual volumes, the way the fallback sums *_usd parts when no preferred alias is present, so that the ledger is not left without a cost."]'::jsonb, 2, 'The same door lets an amount_usd column holding thousands of USD through at one thousandth of its value; after the door, the engine believes you.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 1, 'AKATA sets oil_price_usd_bbl=82 with oil_price_escalator_pct=2 from base_year 2029, and the ledger applies 82.000000 then 83.640000. What does 2031 read?', '["82 plus two equal steps of the first year''s increment, so the six decimals read as zeros.", "87.019056, because the escalator counts from the first production row rather than from base_year, which puts 2031 three steps out.", "85.312800, which is 83.640000 escalated again at 2 percent; each step is larger than the one before.", "82.000000, because a flat price holds until a deck entry moves it."]'::jsonb, 2, 'The six decimals are the compounding made visible: 85.312800 in 2031 and 87.019056 in 2032, each escalated from the year before.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 2, 'The resolver is asked for a flat 80 with a 10 percent escalator from base year 2030, for the year 2029. What comes back?', '["72.727273, de-escalated one year, because the base year is the anchor and not the first year of production.", "80.000000, since the flat price is the starting price and applies unchanged to every year up to the base year, where the escalator begins.", "88.000000, because the escalator counts years away from the base year in either direction and compounds upward on both sides of it.", "Nothing, because the resolver refuses years before the base year."]'::jsonb, 0, 'The same call returns 66.115702 for 2028 and 88.000000 for 2031, so a reader who assumed the flat price was the starting price will not find it in a first row dated before the base year.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 3, 'With the escalator at 10 percent and no deck, the resolver returns 128.840800 for 2035. What does the engine refuse on this path?', '["A price above the 100 anchor of the deck, which is why the resolver holds the last deck price beyond the last entry rather than escalating it.", "An escalator above the inflation rate, since a real price cannot rise faster than money loses value.", "Nothing at all, including an unset oil price, which it fills from the gas price.", "Only a missing price: an escalator compounds without a ceiling, and 128.840800 is the engine doing what it was told."]'::jsonb, 3, 'oil_price_unset stops the run when oil volumes are present and oil_price_usd_bbl is not set; whether 128.840800 is a price anybody will pay is not the engine''s question.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 4, 'escalator_defaults_to_inflation sets inflation_rate_pct=5 and leaves oil_price_escalator_pct out, with oil_price_usd_bbl=100 in base_year 2030. What is the 2031 applied price?', '["100.000000, because a blank escalator means flat, exactly as opex_escalator_pct=0 does in flat_escalator.", "105.000000, because an unset escalator falls back to the inflation rate.", "110.000000, because the escalator defaults to the discount rate of 10 percent when it is not set.", "The run is refused, since an escalator is required whenever an inflation rate is set."]'::jsonb, 1, 'A blank is not a zero: flat_escalator wrote opex_escalator_pct=0 explicitly and got flat opex, while the blank here gave revenue 105000000.00 in 2031.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 5, 'deck_step_hold sets a deck of 100 in 2030 and 50 in 2032 with a 10 percent escalator. What does 2031 read?', '["110.000000, the 2030 entry escalated by 10 percent, because the escalator runs in every year that has no entry of its own.", "100.000000, held from the 2030 entry: not escalated and not interpolated toward 50.", "50.000000, because the deck steps when the next entry is read and the engine looks ahead to it.", "The midpoint of the two entries, because a deck is a curve through its points."]'::jsonb, 1, 'Between entries the last price holds, which is why a two-point deck typed as a forecast holds 100 for a full year and then drops.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 6, 'In the same deck_step_hold case, what does 2033 read, and why?', '["55.000000, the last deck price of 50 escalated by 10 percent, because the escalator only runs past the last entry.", "50.000000 held for every later year, since a deck''s last price is its terminal price and the escalator belongs to the flat price.", "60.500000, two escalations from 50, because the escalator counts every year since the base year 2030.", "110.000000, the flat price of 100 escalated, because the deck has ended and the flat price returns."]'::jsonb, 0, 'Total revenue over the four rows is 305000000.00, and fed the same deck the resolver continues 60.500000 and 66.550000 for 2034 and 2035.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 7, 'The resolver is handed a flat price of 80 together with the deck_step_hold deck. Where does the 80 appear?', '["In the years before 2030, because the deck starts at its first entry and the flat price fills the years before it.", "In 2031, because a year with no entry falls back to the flat price rather than to the entry before it.", "After 2032, when the deck has run out.", "Nowhere: a deck replaces the flat price for every year, including years the deck does not name."]'::jsonb, 3, 'Once a deck exists the flat price is dead, before the first entry and after the last.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 8, 'deck_before_first_entry has entries for 2031 and 2032 only, the 2031 price written as the string "90" under the long key oil_price_usd_bbl, and a flat oil_price_usd_bbl=100. What does 2030 read?', '["100.000000, the flat price, since the deck has no entry for 2030 and the flat price fills years before the deck.", "The run is refused, because the deck price 90 is a string and the key oil_price_usd_bbl is not the short oil key the deck expects.", "90.000000, the first deck entry''s value; the flat 100 is never applied.", "0.000000, because the deck has no entry for 2030 and a deck disables the flat price."]'::jsonb, 2, 'Years before the first deck year take the first deck value, and the engine accepted both the string and the long key: the ledger reads 90.000000, 90.000000, 70.000000.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 9, 'deck_differential has a one-entry deck of 100 in 2030, a 10 percent escalator and oil_price_differential_usd_bbl=-5. What does 2031 read?', '["105.000000: the last entry is escalated from 100 to 110 first, and the differential comes off after.", "95 escalated by 10 percent, because the differential is applied to the benchmark and the gap then escalates with the price.", "100.000000, because the differential applies only in the deck''s own years and 2031 is outside the deck.", "110.000000, because a differential is a one-off adjustment to the base year price that the escalator then overrides."]'::jsonb, 0, 'The order is fixed, resolve then adjust: the case''s own note says differential -5 after deck resolution, and the gross revenue is 95000000.00 then 105000000.00.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 10, 'Which of the two adjustments is worth more the higher the benchmark goes?', '["The differential, because it is applied after the escalator and so compounds with it, while the scale is applied once to the base year price.", "The scale: 1.2 turns 100 into 120 and a higher benchmark into proportionally more, while the -5 differential is worth the same in a low year and a high year.", "Neither, because both are applied to the resolved price and so both grow with it.", "The differential, since a fixed gap is a larger share of a low price."]'::jsonb, 1, 'A differential is a quality or location adjustment that keeps a fixed gap; a scale keeps a fixed ratio.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 11, 'A reader sets both the -5 differential and the 1.2 scale on the same one-entry deck. Which is applied first?', '["The differential, because the case notes say differential -5 after deck resolution and scale multiplies the resolved deck price, which puts the scale last.", "The scale, because a multiplier is always resolved before an addition in the resolver.", "It cannot be stated from the published cases: none sets both, so run them together and read the applied price before assuming either order.", "It does not matter, since the two adjustments commute."]'::jsonb, 2, 'A scale applied to a price already carrying a -5 differential moves the differential too, so the order matters, and the published cases exercise them one at a time.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 12, 'deck_differential''s ledger shows applied_oil_price 95.000000 in 2030. What in the ledger tells a reader that this is a 100 benchmark with a -5 differential rather than a flat 95?', '["The gross revenue of 95000000.00, which is reported beside the benchmark revenue of 100000000.00 so that the gap of the differential can be read off.", "A differential column beside applied_oil_price, which reads -5 in every deck year and 0.00 in every year the escalator has taken over.", "The note on the row, which the engine writes for every adjusted price.", "Nothing: the column holds the final number and no column carries the benchmark, so the configuration is the only record."]'::jsonb, 3, 'The same for the scale: 120.000000 in the deck_scale row, and the 100 with the 1.2 only in the config.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 13, 'AKATA''s 2029 row reads gross revenue 186032000.00 on 2200000.00 bbl of oil. A reader divides revenue by oil volume to recover the price. What do they get?', '["A number larger than 82.000000, because gas revenue is in the numerator and gas volume is not in the denominator; applied_oil_price is the price.", "Exactly 82.000000, because gross revenue is the oil price times the oil volume and the gas is reported in its own revenue column.", "A number smaller than 82.000000, because royalty has already been taken out of gross revenue.", "83.640000, because revenue is booked a year forward of the price it was earned at."]'::jsonb, 0, 'Gross revenue is 82.000000 times the oil plus 3.200000 times 1760000.00 Mscf of gas, and the row does not show revenue by stream.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 14, 'A deck is entered for oil on a field whose file also carries gas volumes. What happens to the gas price?', '["The gas follows the oil deck at 6 Mscf per barrel, so an oil entry of 100 prices the gas at one sixth of it.", "The run is refused with gas_price_unset, because a deck for one stream leaves the other streams unpriced.", "The gas is held at its base year price with its escalator suspended for as long as the oil deck is in force.", "Nothing: the gas stays on gas_price_usd_mscf and its own escalator, because the parsed oil deck carries gas deck entries 0 and no ratio ties gas to oil."]'::jsonb, 3, 'There is no single deck that moves all three streams: a gas price is set, or the run is refused when gas volumes are present.'),
  ('cashflow', 'beginner', 'module', 'm03-prices', 15, 'A reader wants a flat oil price and flat opex in a world with 5 percent inflation. Which escalators must be written as 0, and which can be left blank?', '["All three can be left blank, since inflation only enters the real basis and the ledger here is nominal.", "Oil and opex must be written as 0, because a blank falls back to the inflation rate; only the capex escalator is safe to leave blank, since it stays at 0.", "None can be left blank, because every blank escalator is refused the way a blank price is refused with oil_price_unset.", "Only the oil escalator must be written, because opex is a cost and costs never escalate unless opex_escalator_pct is set."]'::jsonb, 1, 'escalator_defaults_to_inflation shows the fill: revenue 205000000.00 against 200000000.00, opex 20500000.00 against 20000000.00, and no column says which escalator was typed and which was blank.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 1, 'AKATA''s 2029 row reads gross revenue 186032000.00 USD, opex 24000000.00, capex 210000000.00 and net cash flow -121123680.00. What does the JV royalty at jv_royalty_pct 15 read on that row?', '["Nothing, because the row nets -121123680.00 and a royalty is a share of what the year made rather than of what it sold.", "Fifteen percent of 186032000.00 less the 24000000.00 opex, because a royalty is levied on the net operating income the field actually cleared.", "27904800.00, fifteen percent of the 186032000.00 of sales, before any cost is seen.", "Fifteen percent of the taxable income of 113127200.00, since royalty is deductible and so must be computed on the same base as tax."]'::jsonb, 2, 'Off the top means a share of sales, not of profit: 2035 pays 10998867.98 on 73325786.51 in exactly the same proportion, and 2029 pays 27904800.00 while it loses money.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 2, 'On the hand-derived case the royalty is moved from 10 to 30 percent, so the year 1 royalty line rises by 20000000.00 USD. The year 1 net moves only from -7500000.00 to -17500000.00. Where did the other half go?', '["Into the tax base: royalty is deductible, so year 1 tax fell from 37500000.00 to 27500000.00 and the treasury handed half of its own royalty back at the 50 percent rate.", "Into depreciation, which absorbs a larger royalty by spreading it across the schedule.", "Into the working interest, which scales the royalty line before it reaches the net.", "Nowhere: the engine caps the JV royalty so that only half of any change reaches the row."]'::jsonb, 0, 'Each ten points of royalty adds 10000000.00 to the royalty line and takes 5000000.00 off tax, so the net moves 5000000.00 a step, and the take still rises from 65.3846 to 88.4615 percent.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 3, 'AKATA spends 210000000.00 USD in 2029 and 45000000.00 in 2030. Its depreciation column reads 21000000.00 in 2029 and 25500000.00 in every year from 2030 to 2035. Why does the line step once and then hold?', '["The schedule is declining balance, so the charge is front loaded onto the two years that carried capex and then flattens onto the remaining book value.", "The schedule is unit-of-production and follows the oil, which falls from 2200000.00 bbl to 1850000.00 and then declines more slowly.", "The 3 percent opex escalator also inflates the depreciation, and 25500000.00 is where it saturates.", "A ten-year straight line starts in each spend year, so the 2030 tranche adds its own tenth from 2030."]'::jsonb, 3, 'Two tranches, two tenths, added: the line is a schedule on the spends, and it never looks at production or prices.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 4, 'Over its seven rows AKATA''s default schedule claims 174000000.00 of the 255000000.00 spent. What does the engine do with the rest when the field ends in 2035?', '["It writes the gap off in 2035 as a terminal deduction, which is why the 2035 tax is only 3267865.37.", "Nothing. There is no terminal write-off, so the unused deductions are simply never taken.", "It carries the gap forward as loss_carryforward on the last row, where a later run could claim it.", "It refunds the tax value of the gap as a negative tax line in the final year."]'::jsonb, 1, 'A slow schedule leaves value on the table when the field is short, and total tax of 148425219.46 is the cost of it; the seven-year schedule claims 248571428.57 and pays 119700211.23.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 5, 'Set jv_psc_depr_years to 5 and then to 1 on AKATA. Both claim the whole 255000000.00 and both land on total tax 116025219.46 USD. In the ledger this tier reads, are they the same project?', '["Yes in every sense, because a ledger without a clock has no column in which two identical totals could differ.", "Yes on every total, and no on timing: the one-year schedule pays 0.00 in 2029 and 2030 and 32193714.85 in 2031, while the five-year schedule pays 36850880.00 in 2029.", "No, because the one-year schedule carries a loss and the engine refunds it, which the totals hide.", "No, because the five-year schedule claims 9000000.00 in 2034 that the one-year schedule never sees."]'::jsonb, 1, 'The Associate reading stops at the totals and says they agree; what a clock does to that agreement is the Professional tier''s subject.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 6, 'A reader''s hand-built AKATA ledger shows a 2029 net that is 21000000.00 USD below -121123680.00 and a 2031 net that is 25500000.00 below 64468245.07. Which convention did they break?', '["They deducted capex from the tax base instead of depreciation, so the 2029 tax read 0.00 and the shortfall is the missing tax.", "They took the royalty off revenue less opex rather than off gross revenue, which shrinks the royalty and enlarges the tax.", "They forgot the royalty deduction against tax, so the base was larger than 113127200.00 in every year.", "They charged depreciation to cash."]'::jsonb, 3, 'The signature is exact: the gaps are the depreciation charges of those years, and the field comes out 174000000.00 poorer than the engine says.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 7, 'AKATA''s 2029 taxable income is 186032000.00 less 27904800.00, less 24000000.00, less 21000000.00, which is 113127200.00 USD, and tax at 40 percent is 45250880.00. Why does a year that nets -121123680.00 pay any tax at all?', '["Capex is not deductible when spent; only its depreciation of 21000000.00 is, so the tax authority sees a year that earned 113127200.00.", "Because the JV tax is levied on gross revenue and the deductions only reduce the royalty.", "Because the loss carryforward kill switch is on by default under JV, so a loss year is clamped at zero and taxed as though it had earned its gross revenue.", "Because capex lands in December and the tax is assessed on the year before it arrives."]'::jsonb, 0, 'The cash view and the tax view disagree, and both are printed; the loss columns read 0.00 because no AKATA base ever went negative.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 8, 'With jv_tax_rate_pct set to 85 the hand-derived case prints year 1 net -35250000.00, year 2 net 14750000.00 and take 115.7692 percent. What does the take say?', '["The engine has overflowed, since a share of value cannot exceed 100 percent and the column should be read as 15.7692.", "The 85 percent rate was applied to the royalty line as well as the base, double counting 20000000.00.", "The government collects more than the pre-take value the field created, and the contractor''s two years net to a loss.", "The working interest fell below 100, which is the only way the take column moves above the tax rate."]'::jsonb, 2, 'A rate is not a share: at zero tax the same two rows give 30.7692 percent, all of it royalty, and the base decides what any rate is worth.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 9, 'loss_offset_used and loss_carryforward read 0.00 on every AKATA row. Why?', '["The loss mechanism is switched off under the JV regime by default and only the PIA cascade carries a pool.", "No AKATA year''s taxable income goes negative; the smallest base is 8169663.42 in 2035.", "A loss was banked in 2029 and consumed inside the same row, so both columns net out.", "The engine deducts the 210000000.00 of capex from the base in 2029 and reports the resulting loss elsewhere."]'::jsonb, 1, 'The base shrinks every year as revenue falls and opex escalates, but it stays positive, so nothing is carried and the kill switch never matters.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 10, 'AKATA nets 31746007.20 USD in 2030 and 64468245.07 in 2031, while 2030''s gross revenue of 159564720.00 is higher than 2031''s 136363147.20. What explains the smaller 2030 net?', '["Depreciation steps up from 21000000.00 to 25500000.00 in 2030 and is charged against the cash of that year.", "Opex escalates from 24000000.00 to 24720000.00 in 2030, and the 3 percent step falls entirely on that row.", "The 2030 oil price of 83.640000 is below the 2031 price of 85.312800, so the barrels earn less.", "The 45000000.00 second capex tranche lands in 2030."]'::jsonb, 3, 'Depreciation contributed nothing to the answer except through tax, 34164004.80 against 25978830.05; the cash line is capex, and 2031 is the first year without any.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 11, 'AKATA''s 2033 row carries net_cash_flow 44874457.77 USD and real_net_cash_flow 39870374.51. On the hand-derived case the two columns are identical in both years. Why?', '["AKATA runs with inflation_rate_pct 3, so the real column restates each year in 2029 money; the hand-derived case has inflation 0.", "The real column is the net after working interest, and the hand-derived case runs at 100 percent.", "The real column is the discounted cash flow at 10 percent, which on the 2033 row reads 30649858.46.", "The real column subtracts depreciation, and the hand-derived case has only 5000000.00 of it."]'::jsonb, 0, 'Both are the same cash; which one you total is a convention, 141637829.18 nominal against 117362408.71 real, and this tier reads net_cash_flow as printed.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 12, 'AKATA at a 60 percent working interest prints 2029 royalty 16742880.00, tax 27150528.00 and net -72674208.00 USD, with gross revenue still 186032000.00. What scales and what does not?', '["Gross revenue and the volumes scale first, so the cascade runs on 60 percent of the field''s 186032000.00 and the royalty is 15 percent of that share.", "Only the net cash flow scales; the row prints royalty and tax at the field''s 27904800.00 and 45250880.00.", "Royalty, tax and net cash flow scale; gross revenue, the 9680000.00 bbl of oil and the unit technical cost of 40.006602 stay field-level.", "Nothing on the row scales; the working interest is applied to the totals and the NPV only."]'::jsonb, 2, 'Scaling inside means the fiscal cascade runs once on the whole field and the partner takes a share of each result, which is why the engine reports working_interest_pct beside the run.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 13, 'At a 25 percent working interest AKATA''s take reads 91.5431 percent against 66.1723 at 100 percent. What changed?', '["Nothing in the regime. The take compares the partner''s scaled net with the field''s unscaled pre-take value, so it counts the other partners'' share as if it were the government''s.", "The royalty, which the JV regime levies at a higher tier on a small partner''s barrels, so that a 25 percent holder pays a larger share of its revenue off the top than the field does at 100 percent.", "The tax rate, which the engine raises on a minority interest.", "The unit technical cost, which rises when the volumes are scaled and the cost is not."]'::jsonb, 0, 'The government''s share of the field is the 66.1723 percent on the 100 percent row whatever interest is held; 91.5431 is the share of value this partner does not keep.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 14, 'Under AKATA''s flat 15 percent royalty and 40 percent tax, scaling the volumes to the interest first would give the same net as scaling the results afterward. Why does the engine still insist on scaling inside?', '["Because the engine reads the volumes at the working interest before pricing them, so scaling inside and scaling outside are the same calculation and the choice is only a label.", "Because a rate tier on the field''s daily production, a lifetime cumulative cap or a fixed lump sum is not proportional to revenue, and the two orders then part.", "Because the depreciation schedule is unit-of-production and follows the scaled barrels.", "Because the two orders never give the same answer, even under flat rates."]'::jsonb, 1, 'Under flat rates every line is proportional to revenue, so the habit is formed where it is cheap: interest is applied to results, not to inputs.'),
  ('cashflow', 'beginner', 'module', 'm04-the-joint-venture-cascade', 15, 'AKATA sells 1240000.00 Mscf of gas at 3.329280 USD/Mscf in 2031 beside its oil. What royalty rate does the gas revenue carry under the JV?', '["A lower gas tier, which is why the 2031 royalty of 20454472.08 is less than 15 percent of the row''s revenue.", "None, because the JV royalty is levied on oil and the gas is sold royalty free at its own price.", "A rate set by terrain and water depth, which AKATA carries as shallow water.", "The same 15 percent as the oil, one rate on the one gross revenue of 136363147.20."]'::jsonb, 3, 'The JV royalty has no tiers by rate, no price component, no terrain and no allowance; those belong to the PIA regime and to the Expert tier.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 1, 'Add AKATA''s net_cash_flow column through 2030 and you get -89377672.80 USD. The engine''s cumulative_cash_flow column reads -90302313.79 for the same year. Which is the running sum?', '["Only the first; the engine''s column has subtracted the 45000000.00 second capex tranche a second time, once as capex and once as depreciation.", "Both are. The engine''s column follows the real basis, so it sums real_net_cash_flow: -121123680.00 plus 30821366.21.", "Only the second; the first is wrong because it sums money of the day, which is not a cash column.", "Only the second; the engine''s column is the running sum of the discounted cash flow at 10 percent."]'::jsonb, 1, 'A reader who does not know which basis the run is on cannot say which number is the cumulative; on the hand-derived case, with inflation 0, the two columns coincide.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 2, 'AKATA spends 255000000.00 USD of capex, but the cumulative column never falls below -121123680.00. Why is the exposure smaller than the spend?', '["Because the trough is stated after depreciation, and 21000000.00 of the 2029 spend has already been deducted from it.", "Because the engine states the trough at the working interest and the capex at field level, so the two are on different bases.", "Because the second tranche is deferred by the escalator and lands in the cumulative a year late.", "The 2029 sales covered part of the 2029 spend, and 2030 nets 31746007.20 even after its 45000000.00."]'::jsonb, 3, 'The trough is the most the contractor is ever out of pocket, and it sits in 2029, before the second tranche, because production is already covering the build.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 3, 'Which pair of numbers reproduces AKATA''s payback_years of 3.461632?', '["The nominal cumulative of -24909427.73 at the end of 2031 against the 2032 nominal net cash flow of 53959532.44.", "The displayed cumulative of -29534809.71 at the end of 2031 against the 2032 real net cash flow of 49380616.06.", "The displayed cumulative of -29534809.71 against the 19845806.34 it becomes at the end of 2032.", "Three whole rows plus the 2032 share of the peak 2031 flow of 64468245.07."]'::jsonb, 0, 'The engine''s payback walks the nominal running sum while its cumulative_cash_flow column shows the real one; same year, different decimal, so quote payback_years and name its column.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 4, 'AKATA''s cumulative crosses zero in 2032, the fourth row, and the engine prints 3.46 years. From where are the three whole years counted?', '["From first oil, which is why a field whose production starts late reads a longer payback than one that starts at once.", "From the last capex year, 2030, because payback measures the time to recover the final tranche of investment.", "From the first row of the ledger, 2029.", "From the trough, since exposure is what payback is recovering and the trough is where exposure peaks."]'::jsonb, 2, 'Measured from the 2030 tranche the same crossing reads a year shorter and the field looks faster than the engine says.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 5, 'The hand-derived case reads -12500000.00 USD after 2030 and 25000000.00 after 2031, and the engine prints payback_years 1.333333. Where does the third come from?', '["From the hole over the 50000000.00 of capex, which is the fraction of the investment still unrecovered at the end of 2030.", "12500000.00 of the 37500000.00 earned in 2031 is needed to fill the hole.", "From 2031''s share of the two-year total of 25000000.00, which is the fraction of the ledger that comes back after the crossing.", "From the royalty rate of 20 percent applied to the crossing year, since royalty is what delays a payback."]'::jsonb, 1, 'One whole year, then a third of the second: the interpolation is inside the crossing year, on that year''s flow.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 6, 'zero_rates_capex_only reads -60000000.00 then -70000000.00 USD and never turns positive. What does the engine print for payback, and what would a spreadsheet that returns 0 be saying?', '["It prints \"Beyond project life\" with payback_years null; a 0 would claim the field paid back on its first day, which is the single_year_positive label.", "It prints \"Year 0\" with payback_years 0.000000, because the ledger has no crossing to interpolate.", "It prints the last row, 2031, as the payback year and leaves the fraction blank.", "It refuses the run, because a cumulative that never crosses is an upload the engine cannot read."]'::jsonb, 0, 'Neither label is a number: "Year 0" means the first row was already positive, and null means the money never came back.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 7, 'AKATA earns 30401798.05 USD in 2035, three years after its payback. What does that year do to payback_years?', '["It shortens it, which is why 3.461632 is less than the four whole rows the crossing sits in.", "It enters through the discounted payback of 3.961607, which weights the tail years and is the reading that knows about 2035.", "Nothing. Payback sees nothing after the first crossing.", "It would be reported as a second crossing if the tail took the cumulative negative again."]'::jsonb, 2, 'A field that stops the day after payback gets the same 3.46 years, and a cumulative that dips negative again late is not flagged.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 8, 'multiyear_jv_real turns from -40339805.83 to 1742002.07 USD between 2031 and 2032, and the engine prints payback_years 2.889357. What does the size of that first positive cumulative say?', '["Nothing, because the interpolation inside 2032 already accounts for how narrowly the crossing was made.", "That the field is exposed for 40339805.83 at its worst, which is the trough the payback recovers.", "That 2032''s flow was only 1742002.07, so the field is close to its economic limit.", "The crossing clears zero by very little, so a modest price cut would move payback a whole year."]'::jsonb, 3, 'payback_years reports a decimal, not a margin: a crossing made by 1742002.07 and one made by tens of millions print the same kind of number.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 9, 'AKATA''s total opex is 183899092.34 USD, not seven times the typed 24000000. Why?', '["The total is restated in 2029 money by the inflation rate of 3 percent, so it drifts from the typed amount.", "The 3 percent opex escalator carried the column from 24000000.00 in 2029 to 28657255.12 in 2035, and the total is the sum of the escalated column.", "The total includes the 45000000.00 second capex tranche, which the engine books in the opex lane.", "The total is scaled by the working interest, which AKATA carries at less than 100 percent."]'::jsonb, 1, 'The capex total is exactly 255000000.00 because its escalator is 0; each money total is the sum of its column in money of the day.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 10, 'AKATA''s totals are 9680000.00 bbl of oil and 7744000.00 Mscf of gas, and the engine reports 10970666.67 boe. On what basis was the gas converted?', '["Price, at the ratio of 82 USD/bbl to 3.2 USD/Mscf, so that a barrel of equivalent means a barrel of equivalent revenue.", "Volume, at one barrel per Mscf, which is why the boe is larger than the oil alone.", "Revenue share, so that the gas counts in proportion to what it earned in each year.", "Energy, at a fixed 6 Mscf per barrel."]'::jsonb, 3, 'Six Mscf sell for a small fraction of what a barrel does and the boe count does not care; that is its limit and its use, and it flatters the gas.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 11, 'AKATA''s unit technical cost is 40.006602 USD/boe. What happens to it when the working interest drops to 40 percent?', '["It falls to 40 percent of itself, because capex and opex are money lines and every money line scales with the interest the partner holds.", "It rises, because the volumes are scaled to the interest while the capex and opex are not.", "Nothing: it stays at 40.006602, because 255000000.00 plus 183899092.34 over 10970666.67 boe is field-level on both sides.", "It becomes null, because the engine declines to divide a partner''s cost by the field''s barrels."]'::jsonb, 2, 'Neither unit cost contains royalty or tax; they are what it takes to build and run the field per barrel, at any interest.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 12, 'zero_rates_capex_only prints null for both unit costs, and single_year_positive prints 10.000000 USD/boe for both. Why the two results?', '["The first has no volumes, so the engine will not divide by nothing; the second has no capex, so unit technical cost collapses to opex per boe.", "Both are the engine''s zero, printed as null when the field lost money and as the opex rate when it did not.", "The first has no revenue, so the ratio is undefined; the second has revenue of 100000000.00, so the cost can be spread over what that revenue was earned on.", "The first is a JV loss case with the kill switch on; the second is a case with no tax."]'::jsonb, 0, 'Null is the engine declining to invent a ratio with nothing underneath it, and it does the same for take on the same case.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 13, 'A press release quotes AKATA''s government share as royalty plus tax over the 857602518.80 USD of revenue. How does that compare with the engine''s take of 66.1723 percent?', '["It is the same, because royalty and tax are the only two government lines and total revenue of 857602518.80 is the only base a share of it can be quoted on.", "It is smaller, because take divides by revenue less capex 255000000.00 less opex 183899092.34, the value the field created, not by sales.", "It is larger, because the pre-take value adds back the depreciation of 174000000.00 that the tax base removed.", "It cannot be compared, because take is discounted and the press figure is not."]'::jsonb, 1, 'Take is over value, not sales; the rest of that value is the contractor''s total net cash flow.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 14, 'elt_royalty_tail prints take 131.2500 percent and jv_loss_carryforward prints 125.0000. What makes a take pass 100?', '["A royalty rate above 30 percent, which on the hand-derived case already lifts the take to 88.4615.", "The discounted take being added to the undiscounted one when a field runs on the real basis.", "Rounding on a ratio whose denominator is tiny.", "The contractor''s total net cash flow is negative."]'::jsonb, 3, 'Whenever the government collects more than the pre-take value, the contractor''s share is a loss and the take exceeds 100; with no revenue at all the engine prints null instead.'),
  ('cashflow', 'beginner', 'module', 'm05-adding-up', 15, 'Setting AKATA''s depreciation to one year lowers total tax from 148425219.46 to 116025219.46 USD, and the take moves. Does the take know when the tax was paid?', '["No. It moves only because less was collected in total; the discounted take of 76.1610 percent is the version with a clock, and it belongs to the Professional tier.", "Yes, because take is computed year by year and then averaged, so a schedule that defers tax lowers it.", "Yes, because the pre-take value is discounted at 10 percent before the government''s share is divided by it.", "No, but only because the pre-take value is undiscounted; the government''s share is summed year by year at the applied real rate of 6.796117 percent, so a deferred tax counts for less."]'::jsonb, 0, 'Take has no clock: it ignores when the government collects and when the contractor spends, which is the whole limit of the undiscounted reading.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 1, 'The Associate reading is walked on AKATA''s 2031 row rather than on 2029 or 2030. What makes 2031 the cleanest row in the field?', '["It is the base year, so its prices are the typed 82 and 3.2 and no escalator has to be undone before the row can be checked.", "It is the payback year, so the cumulative crosses zero on it and the whole ledger can be checked from one row.", "It carries no capex, no loss and is one year past the last spend, so every column shows its ordinary behaviour.", "It is the peak revenue year, at 136363147.20 USD, so every line is at its largest and easiest to read."]'::jsonb, 2, 'The 2031 net of 64468245.07 is the peak, but the row is chosen for what it lacks: the 45000000.00 tranche is a year behind it and the cumulative is still -29534809.71.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 2, 'AKATA''s 2031 row applies 85.312800 USD/bbl and 3.329280 USD/Mscf where the configuration typed 82 and 3.2. Which setting produced the difference?', '["The price escalators of 2 percent, compounded for the two years since the 2029 base.", "The inflation rate of 3 percent, which the engine applies to every money column including the prices.", "A price deck, which steps the prices in the years it names and holds them between entries.", "The oil price differential, added after the flat price is resolved for each year."]'::jsonb, 0, 'The 2030 row already reads 83.640000, one step, and 85.312800 is that step taken again; the opex column runs on its own 3 percent to 25461600.00.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 3, 'The first step of working a ledger question is to check that the engine will accept the files. What is the reading of a run the engine refuses?', '["A ledger of zeros, from which the reader recovers the missing volumes by reading the annual totals the engine reports back.", "The same ledger the run would have produced, since a refusal only withholds the KPI block and not the rows.", "Whatever the engine produced on the last accepted upload, which it keeps until a new file replaces it.", "The refusal itself, with its reason."]'::jsonb, 3, 'A file that fails is refused with a message, not run with a zero; the only fix for a missing price is the price.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 4, 'A reader builds AKATA''s 2029 row by hand and gets a tax of 0.00 where the engine prints 45250880.00 USD. Which convention did they break?', '["They charged depreciation to cash, which turns 2029 into a loss year with nothing to tax.", "They deducted the 210000000.00 of capex from the tax base instead of its 21000000.00 of depreciation.", "They took the royalty off revenue less opex, which shrinks the base until it goes negative.", "They forgot the royalty deduction, which leaves the base at gross revenue and the tax at zero."]'::jsonb, 1, 'The gap names the mistake: a net 21000000.00 too low is depreciation charged to cash, a tax of 0.00 is capex in the base, a royalty below 27904800.00 is a royalty taken off something net.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 5, 'The second proven row is 2030, chosen because the base year hides the escalators. A reader''s 2030 opex still reads 24000000.00 USD where the engine prints 24720000.00. What was missed?', '["The working interest, which scales the opex line along with the other money lines.", "The capex escalator, left at its default of 0.", "The opex escalator of 3 percent, applied for one year from 2029.", "The inflation rate, which restates the opex in money of the day on a real-basis run."]'::jsonb, 2, 'If the price is still 82.000000 in the 2030 row the oil escalator was not applied, and if the opex is still 24000000.00 the opex escalator was not; 2030 tests both at once.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 6, 'A ledger question is asked at a working interest below 100 percent. What does the Associate method do with the take?', '["Quotes 66.1723 percent from the 100 percent row, because that is the only row on which the number is the government''s share.", "Scales it by the interest, as it scales every other money reading in the KPI block.", "Quotes the take the engine prints at that interest, since the engine reports working_interest_pct beside it.", "Leaves it out, because take is a field-level reading and cannot be stated for a partner."]'::jsonb, 0, 'The money readings scale and the volumes and unit costs stay at field level; the take at an interest compares one partner''s net with the whole field''s value and is not a fiscal statement.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 7, 'One of the four checks says the last cumulative equals the total net cash flow. On AKATA which number is that?', '["141637829.18, the nominal total, because the totals block is stated in money of the day.", "30401798.05, the 2035 net cash flow, since the last cumulative is the last row''s flow.", "19845806.34, the first positive cumulative, because the check is made at payback.", "117362408.71, the close of the real column."]'::jsonb, 3, 'The displayed cumulative_cash_flow follows the basis of the run, and AKATA runs real; the nominal running sum closes at 141637829.18 and is not what the check reads.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 8, 'The method proves 2029 and 2030 to the cent and trusts the remaining rows on the strength of them. What does that not protect against?', '["A wrong price, because a price error is invisible in the base year and the escalated 2030 row only proves the escalator.", "A convention that only bites in a later year, such as a loss carried or a limit reached.", "A wrong working interest, because the interest is applied after the rows are built and cannot be seen in them.", "Nothing, because a ledger right for two rows is right by the same arithmetic everywhere."]'::jsonb, 1, 'AKATA''s loss columns read 0.00 on every row, so nothing in it ever exercises that edge, and two proven rows cannot say what happens when one does.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 9, 'A production upload has oil volumes and the run stops with oil_price_unset. What is the fix?', '["Set the oil price escalator, which the engine reads as the price when the flat price is blank.", "Rename the oil column so the check does not fire.", "Set oil_price_usd_bbl. The method cannot rescue a refused upload.", "Leave it, because the engine falls back to the inflation rate for a price the way it does for an escalator."]'::jsonb, 2, 'An escalator left blank falls back to inflation; a price left blank is a refusal, because a price default would be a number from nowhere.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 10, 'AKATA''s total net cash flow is 141637829.18 USD in money of the day and 117362408.71 in 2029 money. Which one does the Associate reading say a decision should rest on?', '["Neither. It names both with their bases; choosing needs a clock, which is the Professional tier.", "The real one, because a real-basis run reports the real total as total_net_cash_flow and the KPI block is authoritative.", "The nominal one, because payback and take are both read from the nominal running sum.", "The larger one, because money of the day is what was actually received."]'::jsonb, 0, 'Same rows, same cash, two totals; what a 2035 flow of 30401798.05 is worth in 2029 is the question the tier does not answer.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Every Associate reading of AKATA treats the 30401798.05 USD earned in 2035 in one particular way. Which?', '["As 25461027.24, its value in 2029 money, since the run is on the real basis and every total follows it.", "As 17161022.43, its discounted value, because the readings are stated at the applied rate.", "As money the payback can see, because the cumulative includes it.", "As exactly 2029 money."]'::jsonb, 3, 'Nothing in this tier has a clock: payback, take and unit cost alike are undiscounted, and the real column is a restatement, not a valuation.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 12, 'The engine prints take 66.1723 and 76.1610 percent, and payback 3.461632 and 3.961607 years, on the same line. Which of each pair is the Associate reading?', '["76.1610 and 3.961607, because the discounted readings are the ones on the real basis and AKATA runs real.", "66.1723 and 3.461632, the undiscounted ones.", "66.1723 and 3.961607, because take is undiscounted by definition and payback is always discounted.", "Whichever is printed first, since the engine orders each pair by the convention of the run."]'::jsonb, 1, 'The other two are the same readings with a clock, and none of the four can be read until its convention is stated.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 13, 'The tier can say that AKATA pays back in 2032, costs 40.006602 USD per boe and hands the government 66.1723 percent. What can it not say?', '["Whether the field was profitable, since profit needs the tax view and the tier reads only the cash view.", "What the government collected, because take is stated over value rather than as a sum.", "Whether 117362408.71 arriving when it does was worth the 255000000.00 spent in 2029 and 2030.", "When the money came back, because payback is a year and not a date."]'::jsonb, 2, 'The Associate ledger stops at a running sum with no clock, and whether AKATA is a good investment is a question that needs one.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 14, 'AKATA''s field ends when its data ends in 2035, and a year whose revenue no longer covered its opex would still be in the ledger. What decides that?', '["The economic limit is off by default, so a losing tail is kept unless somebody turns it on.", "The JV regime, which has no concept of a tail and so cannot trim one.", "The depreciation schedule, which keeps a year alive until its tenth has been claimed.", "The price escalator, which lifts revenue every year so that no tail ever fails."]'::jsonb, 0, 'A default nobody set decides the shape of the ledger; the limit test, abandonment and the PIA edges are the Expert tier, and each changes a row before it changes a total.'),
  ('cashflow', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Work the hand-derived 2030 row: revenue 100000000.00 USD, royalty at 20 percent, opex 10000000.00, depreciation 5000000.00, tax at 50 percent, capex 50000000.00, net -12500000.00. Which of the four checks can that one row settle on its own?', '["The last cumulative equals the total, since -12500000.00 sits in both.", "Tax is not zero in a year that spent capex: 32500000.00 beside 50000000.00.", "The take sits between the royalty rate and 100 percent, because the row''s royalty and tax are both printed.", "The depreciation column sums to no more than the capex, because 5000000.00 is below 50000000.00."]'::jsonb, 1, 'The other three need the whole ledger: the 2031 row adds another 5000000.00 of depreciation, the cumulative closes at 25000000.00 and the take of 80.7692 is a ratio of totals.'),
  ('cashflow', 'beginner', 'final', null, 1, 'In the hand-derived 2030 row the depreciation column reads 5000000.00 USD, and that number appears nowhere in the net cash flow of -12500000.00. What is the column there for?', '["To spread the 50000000.00 of capex across the two rows so that each year carries its share of the spend in cash.", "To reduce taxable income to 65000000.00, and through the 50 percent rate to cut tax by half of itself.", "To record the part of the capex the engine has already returned to the contractor through the cumulative column.", "To mark the tax value of the royalty, which is deductible and so must be printed as a separate line."]'::jsonb, 1, 'A reader who subtracts depreciation from revenue when building net cash flow gets a row 5000000.00 too low and never sees it, because the arithmetic looks tidy.'),
  ('cashflow', 'beginner', 'final', null, 2, 'AKATA''s oil falls from 2200000.00 bbl in 2029 to 770000.00 bbl in 2035. Where does that decline come from?', '["A decline model fitted by the engine to the first two rows and projected forward at a constant fraction a year.", "The economic limit, which trims the volumes each year as opex escalates against price.", "The depreciation schedule, which retires a tenth of the field''s capacity each year alongside its capex.", "The production upload. The engine models no reservoir and believes the volumes it is given."]'::jsonb, 3, 'If the volumes are wrong the ledger is wrong, and the engine has no way to know; the file listed 770000 against year 2035 and the row repeats it to two decimals.'),
  ('cashflow', 'beginner', 'final', null, 3, 'A capex row carries both amount_usd and cost_usd. Under what condition does the engine refuse the file?', '["Only when the two hold different values; equal values are taken once, not doubled.", "Always, because a row may carry exactly one cost column and the engine will not pick between two preferred aliases.", "Never, because both are preferred aliases and the engine sums every column ending in _usd in that case.", "Only when one of them is prefixed total_, which the fallback excludes from its sum."]'::jsonb, 0, 'ambiguous_cost_aliases says which: different values, refused; the same value, accepted once, and the year''s capex is the value, not twice it.'),
  ('cashflow', 'beginner', 'final', null, 4, 'AKATA''s 2030 row prints applied_oil_price 83.640000 USD/bbl. Why does the course insist on quoting six decimals rather than 83.64?', '["Because the engine rounds internally to six places and a shorter figure would not reproduce the gross revenue of 159564720.00.", "Because prices below 100 need six decimals to carry the same precision as the money columns, which carry two.", "Because the decimals are what let a reader check the escalator''s work against the engine, and a rescale throws that away.", "Because 83.64 would be read as a percentage by the configuration, which stores rates and prices in one field."]'::jsonb, 2, 'Money is printed to two decimals, volumes to two, prices to six, rates to four; the engine never changes a unit or a precision, and neither should a reader.'),
  ('cashflow', 'beginner', 'final', null, 5, 'jv_royalty_pct is entered as 15 for AKATA. What does the engine do with a reader who types 0.15 instead?', '["It refuses the run, because a royalty below 1 percent is outside the range the JV regime accepts.", "It reads the fraction as a percent value and reports the same 27904800.00 of royalty in 2029.", "It runs, at a royalty a hundred times smaller than intended, and nothing objects.", "It scales the value back to 15 by comparing it with the tax rate of 40."]'::jsonb, 2, 'Rates are percent values everywhere in the configuration; a file or a field in the wrong unit is believed, and every number downstream carries the error at full precision.'),
  ('cashflow', 'beginner', 'final', null, 6, 'alaoma_csv_ingestion has oil in rows dated 2027-01 and 2027-02, and its flat price runs with an escalator. Which price does the February oil earn?', '["The same price as the January oil, because the month finds the year and is then forgotten; 2027 revenue is 14250000.00 on 190000.00 bbl at one price.", "One month of escalation on the January price, because the escalator compounds from the base date month by month and the row carries a month.", "The base price for both, because escalation starts only in the second calendar year of the ledger and 2027 is the first.", "A price from a deck the engine builds from the row dates, one entry per dated row."]'::jsonb, 0, 'Dating happens before any price is applied, so where a date lands is a pricing decision: a row dated the following January would earn the next year''s escalated price.'),
  ('cashflow', 'beginner', 'final', null, 7, 'fiscal_regime picks one of three cascades from gross revenue to net cash flow. Which description is the JV cascade?', '["Cost recovered from a capped share of revenue and the remainder split, which is why psc_carryforward pays 27000000.00 of tax on 200000000.00 of revenue and nets -1000000.00.", "Five taxes on three bases, which on the published worked example collect 604809283.90 out of 1460000000.00 of revenue.", "One tax on gross revenue with no deductions, which is what the loss columns reading 0.00 on every row implies.", "Royalty, then deductions, then a single tax rate: 20000000.00 of royalty and 32500000.00 of tax out of 100000000.00 in 2030."]'::jsonb, 3, 'Every regime reports the same KPI set; what differs is the cascade between the one gross revenue and the net, and the JV is the flat one.'),
  ('cashflow', 'beginner', 'final', null, 8, 'zero_rates_capex_only runs with total revenue 0.00 USD and prints take null, unit technical cost null and payback beyond project life. Why was it not refused instead?', '["It was refused, and the null readings are what the KPI block prints for any run that stops at the door.", "Refusal is for a file the engine cannot read; this one was readable, and null is the engine declining to invent a ratio with nothing on top.", "Because zero volumes are a valid decline and the engine treats them as the economic limit having been reached in the first row.", "Because the file carried capex rows, and a capex file alone is enough to run without production."]'::jsonb, 1, 'The eight refusals name headers, prices, ambiguity and emptiness; a readable file with nothing sold runs, and its cumulative ends at -70000000.00.'),
  ('cashflow', 'beginner', 'final', null, 9, 'A production file carries w1_oil_bbl_forecast beside a real oil column. What happens to the forecast column?', '["It is dropped without a word, because the suffix must be last and forecast follows it.", "It is summed with the real column, because the prefix w1 marks it as the same well''s oil and the engine adds a well''s columns.", "It is refused as no_volume_columns, because a header that is nearly a volume column is treated as ambiguous.", "It is read as a separate well, since anything before _oil_bbl is a well name."]'::jsonb, 0, 'Alone, the file fails; beside a real column it runs, and the only trace is an annual volume smaller than the spreadsheet''s.'),
  ('cashflow', 'beginner', 'final', null, 10, 'alaoma_csv_ingestion uploads rows dated 2027-01 with oil_bbl=100000 and 2027-02 with oil_bbl=90000, plus days_in_month, liquid_bbl, oil_rate_bopd and watercut_pct. What does the engine read for 2027?', '["Oil 190000.00 bbl, with the two months priced separately and then added, because the date carries the month.", "Liquid volumes, since liquid_bbl ends in _bbl and the engine takes the largest volume column it finds.", "Two rows, one for January and one for February, because the ledger keeps the upload''s period.", "Oil 190000.00 bbl, and none of the other four columns, because none ends in a volume suffix."]'::jsonb, 3, 'The month is used to find the year and then forgotten; there is no cash flow of March in the ledger it returns.'),
  ('cashflow', 'beginner', 'final', null, 11, 'month_index_rows uploads twenty-four production rows of oil_bbl=10000 at month_index 1 through 24 with base_year 2027. What does the ledger hold?', '["Twenty-four rows, one a month, each priced at the escalated price for its month and then summed in the KPI block.", "Two rows, 2027 and 2028, each with 120000.00 bbl, and nothing in it knows the upload was monthly.", "One row in the base year holding all twenty-four months, because a month index counts from the base year and stays in it.", "Two rows of 120000.00 bbl and an empty 2029 row, because month_index=24 closes a year and opens the next."]'::jsonb, 1, 'The result reads total revenue 18000000.00, and its capex at month_index=1 is 2027 capex 5000000.00; months exist on upload and not in the ledger.'),
  ('cashflow', 'beginner', 'final', null, 12, 'per_well_beats_total_rollup carries total_oil_bbl=100000, well1_oil_bbl=60000 and well2_oil_bbl=40000 for 2027 and reports revenue 7500000.00 USD and take 55.0000 percent. Had the total been added to the wells, what would have looked odd in the KPI panel?', '["The take, which would have fallen below the royalty rate because the tax base doubled while the royalty did not.", "The payback, which would have moved from Year 0 to a positive number because the capex stayed at 0.00.", "Nothing. Revenue and every reading built on it would be double, and each would still be a plausible number.", "The DPI, which prints null with no capex and would have become a number once revenue doubled."]'::jsonb, 2, 'The wells are the data and the total is dropped; a reader who sums every _oil_bbl column gets 200000 and concludes the engine lost half the field.'),
  ('cashflow', 'beginner', 'final', null, 13, 'AKATA''s production file carries akata_oil_bbl and akata_gas_mscf. What is akata to the engine?', '["A field tag that tells the engine the two columns belong to one ledger, which is why the gas and the oil are priced together.", "A label it ignores, because only the bare oil_bbl and gas_mscf forms are read and the prefixed forms are carried past.", "The name of the price deck the two streams are resolved against, one deck per prefix.", "A well prefix; anything before the suffix is a well, and the engine sums each stream across every well it finds."]'::jsonb, 3, 'The prefix can be akata, w1 or a real well name as long as the suffix closes the header; a file with many wells needs one oil column per well and one gas column per well.'),
  ('cashflow', 'beginner', 'final', null, 14, 'case_insensitive_headers uploads columns headed Date, Oil_BBL, Cost_USD and Total_Opex_USD. How does the engine read them?', '["As date, oil_bbl, cost_usd and total_opex_usd; case is ignored, so the 2027 opex is 750000.00.", "It refuses the production file, because Oil_BBL is not one of the lower-case suffixes the no_volume_columns message lists.", "It reads the volumes and refuses both cost files, because a preferred alias is matched exactly and Cost_USD is not one.", "It reads them all, but Cost_USD falls through to the fallback sum because only an exact alias is preferred."]'::jsonb, 0, 'OIL_BBL and Oil_BBL are the same column as oil_bbl; the recogniser tests the suffix and the alias, never the case.'),
  ('cashflow', 'beginner', 'final', null, 15, 'A capex column headed amount_usd holds thousands of USD rather than USD. What does the refusal check do?', '["It refuses the file, because the values are too small against the production volumes to be a plausible capex.", "Nothing. The file passes and the capex is read at one thousandth of its value.", "It scales the column by 1000, because the engine detects the magnitude from the other cost files.", "It flags the row as ambiguous, since a preferred alias with an implausible value is treated like two aliases that disagree."]'::jsonb, 1, 'The refusal does not check that the number under a recognised header is the right number; a gas column headed _mscf holding scf is read at a thousand times its value the same way.'),
  ('cashflow', 'beginner', 'final', null, 16, 'A production file fails with no_usable_date, and the reader pastes in a year column with one value on every row. What has happened?', '["The refusal goes away and the engine spreads the rows evenly across the year, because the month index is inferred from row order.", "The refusal goes away and every month lands in one year, and no later refusal will catch it.", "The refusal persists, because a year column with a single repeated value is not a usable date.", "The engine re-dates the rows from the filename and ignores the pasted column."]'::jsonb, 1, 'A refusal is the engine''s only chance to object; after the door it believes you, and the only check left is the annual volumes it reports back.'),
  ('cashflow', 'beginner', 'final', null, 17, 'AKATA applies 82.000000 in 2029, 83.640000 in 2030 and 85.312800 in 2031. Why is 85.312800 not 82 plus two equal steps?', '["The 2031 step includes the inflation rate of 3 percent on top of the 2 percent escalator, so the second year climbs faster.", "The gas escalator is applied to the oil price in the second year, and the two rates add.", "The escalator compounds: 85.312800 is 83.640000 escalated again, and each step is larger than the one before.", "The escalator is linear and 85.312800 is a rounding of the second equal step."]'::jsonb, 2, 'The six decimals are the compounding made visible, and the gas price runs 3.200000, 3.264000, 3.329280 on its own escalator in the same rows.'),
  ('cashflow', 'beginner', 'final', null, 18, 'The three-stream case uploads w_oil_bbl=5000000, w_gas_mscf=30000000 and w_condensate_bbl=300000 for 2025 at 80, 4.5 and 70 with escalators 0, and the row reads gross revenue 556000000.00 USD. What does the row show about the split between streams?', '["Nothing. One revenue number carries all three, and a reader who wants the oil share multiplies the volumes by the prices the row does carry.", "Three revenue columns, one per stream, because each stream has its own price, escalator and deck and the ledger keeps them apart.", "The oil share only, since gas and condensate are folded into boe at 6 Mscf per barrel before they are priced.", "A blended price per boe, which is what applied_oil_price shows on a row with more than one stream."]'::jsonb, 0, 'The JV cascade never needs the split, because royalty and tax are taken from the one gross revenue, which is why the engine keeps only the one number.'),
  ('cashflow', 'beginner', 'final', null, 19, 'With no deck, a flat 80 and the escalator typed as 0, what does the resolver return for the years 2028 through 2035 around a 2030 base year?', '["80.000000 from the base year onward and de-escalated values before it, since the base year is still the anchor for the years behind it.", "80.000000 from 2030 onward and the inflation rate applied before it, because a typed zero only switches off the forward escalation.", "Nothing, because an escalator of 0 is read as unset and falls back to the inflation rate.", "80.000000 in every year, before the base year as well as after it."]'::jsonb, 3, 'Zero means flat; it is a blank, not a zero, that falls back to inflation, and the same call with the escalator at 10 returns 72.727273 for 2029.'),
  ('cashflow', 'beginner', 'final', null, 20, 'A reader sets a 10 percent escalator for a flat price, then enters the deck_step_hold deck, which ends at 50 in 2032. What does the resolver return for 2035?', '["50.000000, because a deck holds its last entry for every later year the way it holds between entries.", "55.000000, because the escalator runs once past the end of the deck and then the price holds.", "66.550000, because past the last entry the escalator runs on the last deck price, a rising tail nobody chose.", "The flat price escalated, because the deck ends in 2032 and the flat price returns for the years after it."]'::jsonb, 2, 'The fix for a deck that should stay at 50 is an escalator of 0, and a reader who set 10 for the flat price and forgot it has a tail nobody chose.'),
  ('cashflow', 'beginner', 'final', null, 21, 'deck_differential sets a one-entry deck at 100 for 2030, a 10 percent escalator and a differential of -5. Why does 2031 read 105.000000 rather than 95 escalated?', '["The order is fixed: resolve the deck and escalate to 110, then add the differential.", "The differential is applied only in deck years, so 2031, past the deck, carries no differential and reads 110 less rounding.", "The differential escalates with the price, so the 2031 gap is larger than 5 and the row is 105 by coincidence.", "The scale of 1.2 was also set on that case, and the two adjustments cancel in 2031."]'::jsonb, 0, 'A reader who applies the differential to the benchmark and then escalates disagrees with the engine by a little more each row and never by enough to look like a bug.'),
  ('cashflow', 'beginner', 'final', null, 22, 'A reader wants a crude at 120 percent of the benchmark and types 20 into oil_price_scale. What happens?', '["The engine reads 20 as a percent and multiplies by 1.2, since every rate field is a percent value.", "The price is multiplied by twenty, and nothing refuses it.", "The run is refused, because a scale above 10 is outside the range the resolver accepts.", "The scale is treated as a differential of 20 USD/bbl, since the two adjustments share a field."]'::jsonb, 1, 'deck_scale shows the intended form: oil_price_scale 1.2 turns the 100 entry into 120.000000, and the configuration is the only record that a scale was used at all.'),
  ('cashflow', 'beginner', 'final', null, 23, 'escalator_defaults_to_inflation sets inflation_rate_pct 5 and leaves the oil and opex escalators blank. What does the 2031 row show?', '["Price 100.000000 and opex 10000000.00, because a blank escalator means flat, and only a typed value escalates.", "Price 105.000000 and opex 10000000.00, because only prices default to inflation and opex defaults to 0.", "Price 100.000000 and opex 10500000.00, because inflation is a cost phenomenon and prices are set by the deck.", "Price 105.000000 and opex 10500000.00, both escalated at the inflation rate, with the capex escalator still 0."]'::jsonb, 3, 'A blank escalator is inflation, a zero escalator is flat, and only the capex escalator is safe to leave blank.'),
  ('cashflow', 'beginner', 'final', null, 24, 'A reader divides AKATA''s 2029 gross revenue of 186032000.00 USD by its 2200000.00 bbl of oil and gets a number above 82.000000. What have they found?', '["That the escalator started a year early, because 82.000000 in the base year should reproduce exactly from the row.", "That the flat price was mis-entered, since gross revenue over oil volume is the definition of the applied price.", "That a differential is in force, because the applied price column hides adjustments.", "Nothing about the price. Gas revenue is in the numerator and gas volume is not in the denominator."]'::jsonb, 3, 'The applied_oil_price column is the price; gross revenue is that price times the oil plus 3.200000 times 1760000.00 Mscf of gas.'),
  ('cashflow', 'beginner', 'final', null, 25, 'None of the published price cases sets a differential and a scale together. What can a lesson say about the order between them?', '["Nothing. The order is not published, it matters, and the only way to know is to run both in the explorer and read the applied price.", "That the scale comes first, because a multiplicative adjustment is always applied before an additive one in the resolver.", "That the differential comes first, because deck_differential resolves before deck_scale in the published order.", "That it does not matter, because the two adjustments commute on any price."]'::jsonb, 0, 'A scale applied to a price already carrying a -5 differential moves the differential too, so the two orders give different rows.'),
  ('cashflow', 'beginner', 'final', null, 26, 'A hand-derived JV ledger shows royalty 20000000.00 USD beside tax 42500000.00 in the same year. What is that the fingerprint of?', '["Royalty taken off revenue less opex, which shrinks the royalty and enlarges the tax in the same row.", "The tax rate mis-entered as 85, which lifts the year 1 tax toward 55250000.00.", "Royalty charged against cash but not removed from taxable income.", "A working interest below 100, scaling tax and not royalty."]'::jsonb, 2, 'At 50 percent tax the 20000000.00 deduction is worth 10000000.00, and 42500000.00 is the tax the engine prints only when the royalty is 0.00.'),
  ('cashflow', 'beginner', 'final', null, 27, 'With jv_psc_depr_years 7, AKATA''s schedule claims 248571428.57 USD of 255000000.00 and total tax reads 119700211.23, against 148425219.46 on the default. Why is the total tax lower?', '["A faster schedule shrinks the base in the early years and the loss carried forward is refunded at cessation.", "More of the capex is deducted inside the seven-year horizon, so less of it is lost when the field ends.", "Tax is charged on the undepreciated balance, and the seven-year schedule leaves less balance.", "The seven-year schedule spreads the opex as well as the capex, which the default does not."]'::jsonb, 1, 'The default claims 174000000.00 in seven years and never writes off the rest; every faster schedule claims more and pays less in total.'),
  ('cashflow', 'beginner', 'final', null, 28, 'Rebuild AKATA''s 2032 net cash flow of 53959532.44 USD from the row: gross revenue 116656473.02, royalty 17498470.95, opex 26225448.00, depreciation 25500000.00, taxable income 47432554.07, tax 18973021.63, capex 0.00. Which lines are subtracted from revenue?', '["Royalty, opex, capex and tax; depreciation is not among them.", "Royalty, opex, depreciation and tax, since the row is built from left to right and every deduction column counts.", "Royalty, opex and depreciation only, because tax is a reading and not a cash line.", "Tax alone, because the taxable income already has royalty, opex and depreciation removed."]'::jsonb, 0, '116656473.02 less 17498470.95, less 26225448.00, less 0.00, less 18973021.63 is 53959532.44 to the cent; depreciation was used once, to reach 47432554.07, and then left.'),
  ('cashflow', 'beginner', 'final', null, 29, 'AKATA at a 40 percent working interest prints 2029 net -48449472.00 USD, take 86.4689 percent and unit technical cost 40.006602 USD/boe. Which of those three is a statement about the field rather than about the partner?', '["Only the take, which is the government''s share and cannot depend on who holds the interest.", "The net and the take together, since both are printed on the partner''s row.", "Only the unit technical cost, which is field-level on both sides of its ratio.", "None of them, because every reading on a scaled run belongs to the partner."]'::jsonb, 2, 'The net is the partner''s share, the take counts the other partners as if they were the government, and 40.006602 is the same at 100 percent and at 25.'),
  ('cashflow', 'beginner', 'final', null, 30, 'A partner''s interest in a field steps from 100 percent to 60 percent after payout. How does the engine model it?', '["With a second run at 60 percent whose rows are spliced in from the payback year the first run reports.", "With the interest applied year by year from a column in the production file, which the engine reads like a volume.", "By scaling the pre-payout rows at 100 and the later rows at 60 automatically, since payback is a reading it already has.", "It cannot: jv_working_interest_pct is one number for the whole life."]'::jsonb, 3, 'Working interest scales money lines only, cannot step at a date, and carries no carried interest and no partner-specific cost.'),
  ('cashflow', 'beginner', 'final', null, 31, 'The hand-derived case at a 25 percent working interest prints year 1 royalty 5000000.00 USD, tax 8125000.00, net -3125000.00 and take 95.1923 percent. What has stayed the same as the 100 percent run?', '["The take, because the regime is unchanged and the take is the regime''s share.", "The volumes, the prices and every field-level line the row prints, because the cascade ran once on the whole field.", "The net cash flow, because scaling is applied to the KPI block and not to the rows.", "Nothing, because a 25 percent partner has a quarter of everything including the barrels."]'::jsonb, 1, 'Royalty 20000000.00, tax 32500000.00 and net -12500000.00 each became a quarter of themselves; 95.1923 is a partner''s number, not a fiscal one.'),
  ('cashflow', 'beginner', 'final', null, 32, 'AKATA''s cumulative_nominal reads 29050104.71 USD at the end of 2032 and its cumulative_cash_flow reads 19845806.34. What do the two agree on and what do they not?', '["They agree that payback falls in 2032, and they disagree on the fraction inside the year.", "They agree on the fraction, because both are interpolated from the same 2032 flow, and disagree on the year.", "They agree on nothing, because one is a running sum and the other a total.", "They agree on the trough and disagree on the sign of the 2032 entry."]'::jsonb, 0, 'The nominal and real columns change sign in the same year, so the whole-year part is the same; the engine''s 3.461632 walks the nominal column.'),
  ('cashflow', 'beginner', 'final', null, 33, 'multiyear_jv_real and multiyear_pia_real both print payback "2.89 years". Do the two fields pay back at the same time?', '["Yes, because the label is the engine''s reading and payback_years is a diagnostic that carries extra digits.", "Yes, because both cross zero in their third row and payback is a year.", "No, because one is a JV field and the other a PIA field, and the regimes count from different rows.", "No. Their payback_years are 2.889357 and 2.892034, and the label is a rounding of each."]'::jsonb, 3, 'Two fields that cross in the same calendar year can be nearly a year apart in payback_years, and two that print the same label can differ in the third decimal.'),
  ('cashflow', 'beginner', 'final', null, 34, 'The hand-derived case reports unit technical cost 35.000000 USD/boe and opex per boe 10.000000. From which totals?', '["Capex 50000000.00 plus opex 20000000.00 over 1000000.00 bbl, the first year''s oil, then the first year''s opex over the same.", "Revenue 200000000.00 less tax 65000000.00 over 2000000.00 boe, then royalty over the same.", "Capex 50000000.00 plus opex 20000000.00 over 2000000.00 boe, then 20000000.00 over the same.", "Capex 50000000.00 plus opex 20000000.00 plus tax 65000000.00 over 2000000.00 boe, then opex over the same."]'::jsonb, 2, 'Neither number contains royalty or tax; the case has no gas, so its 2000000.00 bbl are 2000000.00 boe.'),
  ('cashflow', 'beginner', 'final', null, 35, 'On the hand-derived case take is 65.3846 percent with the royalty at 0 and 30.7692 percent with the tax at 0. What do the two numbers together say?', '["A regime is a take, not a rate: each instrument moves the share on its own axis, and neither rate alone is the government''s share.", "That royalty is the larger instrument, since removing it moves the take further than removing the tax.", "That the two instruments add, so the take with both in force is their sum rather than the 80.7692 the engine prints.", "That take is undefined when either rate is zero, and the engine prints the other rate instead."]'::jsonb, 0, 'With both in force the take is 80.7692 percent; royalty shrinks the tax base, so the two do not simply add.'),
  ('cashflow', 'beginner', 'final', null, 36, 'jv_loss_unused_at_cessation ends at a cumulative of -50000000.00 USD with total revenue 0.00. What does the engine print for take and payback?', '["Take 100.0000 percent, since the government''s share of a total loss is everything, and payback null.", "Take null and payback \"Beyond project life\", with payback_years null.", "Take null and payback \"Year 0\", because one row has no crossing.", "Take 125.0000 percent, because the contractor''s total is negative, and payback null."]'::jsonb, 1, 'Take passes 100 when the contractor''s total is negative but there is value to share; with no revenue there is nothing to share and the engine prints null.'),
  ('cashflow', 'beginner', 'final', null, 37, 'AKATA''s KPI line prints unit technical cost 40.006602 USD/boe, PV of capex 250909090.91 USD, discounted payback 3.961607 years and discounted take 76.1610 percent. Which one belongs to the Associate reading?', '["The PV of capex, because capex is spent in the first two years and needs no discounting.", "The discounted payback, because payback is the tier''s reading and the discounted form is more precise.", "The unit technical cost, which is a lifetime average with no clock in it.", "The discounted take, because AKATA runs on the real basis and the real basis is the discounted one."]'::jsonb, 2, 'The other three carry a rate; the Associate ledger ends before a discount rate is mentioned.'),
  ('cashflow', 'beginner', 'final', null, 38, 'The Associate method builds one row by hand before trusting the engine. Why is the first year, 2029 on AKATA, the row to choose?', '["It is the base year, so no escalator has acted and every line is the typed value, which makes it the easiest row to reproduce.", "It is the trough of the cumulative, and a payback cannot be read until the trough is proven.", "It is the only row on which the real and nominal columns agree, so the basis cannot confuse the check.", "It holds the capex, so a broken convention shows as the largest gap."]'::jsonb, 3, 'The base year also hides the escalators, which is why the second proven row is 2030: applied price 83.640000, opex 24720000.00, net 31746007.20.'),
  ('cashflow', 'beginner', 'final', null, 39, 'A hand-built AKATA 2029 row prints a royalty smaller than 27904800.00 USD and a tax larger than 45250880.00. Which convention was broken?', '["Depreciation was charged to cash, which lowers the net and forces the tax up to balance the row.", "The royalty was taken off something net, and because its deduction against tax shrank with it, the tax grew.", "Capex was deducted from the tax base, which removes the royalty''s share of the base.", "The working interest was applied to the royalty and not to the tax."]'::jsonb, 1, 'The ledger looks plausible and every downstream number is wrong; the fix is the base, which is the 186032000.00 of sales and nothing smaller.'),
  ('cashflow', 'beginner', 'final', null, 40, 'The course calls the null take on zero_rates_capex_only a truer answer than any percentage. Why?', '["There is no value to share, and a number would describe a share of nothing.", "Because the engine cannot compute a ratio when the working interest is not set, and null flags the missing field.", "Because take is only defined on the real basis, and the case runs nominal.", "Because the case was refused at the door and null is what a refused KPI block prints."]'::jsonb, 0, 'Reading what the engine refuses as carefully as what it returns is one of the three habits the tier carries into the others.'),
  ('cashflow', 'beginner', 'final', null, 41, 'AKATA''s real total of 117362408.71 USD is smaller than its nominal total of 141637829.18. Is the real total a discounted number?', '["Yes, because restating in base-year money and discounting are the same operation at the inflation rate.", "Yes, because the real column is the discounted_cash_flow column under another name.", "No. It is the same cash restated in 2029 money by the 3 percent inflation rate; the discounted reading is the NPV of 72534830.66.", "No, because the real total is the nominal total less the depreciation the horizon never reached."]'::jsonb, 2, 'Real is a basis and discounting is a clock; the Associate tier names the basis and leaves the clock to the Professional tier.'),
  ('cashflow', 'beginner', 'final', null, 42, 'A production sharing contract recovers cost from a pool before it shares profit. Would AKATA''s JV ledger show such a pool?', '["Yes, in the loss_carryforward column, which under JV is the cost pool waiting to be recovered.", "Yes, in the depreciation column, since the 255000000.00 spent less the 174000000.00 claimed is the unrecovered cost.", "Only when the economic limit is on, because the pool is what the limit test reads.", "No. The JV regime is one royalty and one tax rate, and the pool belongs to a different regime and a different tier."]'::jsonb, 3, 'AKATA''s loss columns read 0.00 on every row, its royalty is one rate, its tax is one rate, and its field ends when its data ends.');
